// =============================================================================
// services/media/youtube.js — YouTube captions → timestamped transcript segments
//
// OWNER: A38 (Wave 4). Responsibilities:
//   INPUT   a YouTube URL (already validated) + an optional preferred language
//   OUTPUT  { videoId, title, url, durationSeconds, language, isAutoGenerated,
//             segments, cueCount, charCount }
//           `segments` is the array `chunkSegments()` consumes — see below.
//   DEPENDS ON nothing but `middleware/errors.js` (ApiError) and the global
//           `fetch` (Node ≥18). ZERO npm dependencies.
//   TEST    real YouTube URLs (see the A38 verification log); every failure
//           path is an explicit, specific error code — never invented text.
//   EXPORTS `fetchYouTubeTranscript` is the entry point. The pure helpers
//           (`parseYouTubeUrl`, `readCaptionTracks`, `chooseCaptionTrack`,
//           `parseTimedText`, `formatTimecode`, `buildTranscriptSegments`) are
//           exported for unit tests, exactly as `services/extract/webpage.js`
//           exports `normalizeWebpageText` — no route calls them directly.
//
// -----------------------------------------------------------------------------
// HOW THIS WORKS (and why it is the fragile part of the whole feature)
// -----------------------------------------------------------------------------
// YouTube has no free, keyless transcript API. The path used here is the same
// one YouTube's own mobile app uses, so it needs no API key and no package:
//
//   1. POST https://www.youtube.com/youtubei/v1/player  with the ANDROID
//      client identity. The response carries `videoDetails` (title, length) and
//      `captions.playerCaptionsTracklistRenderer.captionTracks` — one entry per
//      available caption track, each with its own `baseUrl`.
//   2. GET that `baseUrl`. YouTube answers with XML `<timedtext>`:
//        <timedtext format="3"><body>
//          <p t="18640" d="3240">&#39;We&#39;re no strangers to love</p>
//        </body></timedtext>
//      `t` is the START time in milliseconds, `d` the duration in milliseconds.
//
// ⚠️ EVERY site-specific detail — the client identity, the JSON paths, the XML
// element names, the query shape — lives in the "SITE-SPECIFIC" block below and
// nowhere else. If YouTube changes any of it, that block is the only place that
// needs editing. Everything below it is transport and time formatting.
//
// ⚠️ THE OTHER RULE: YOUTUBE IS NOT TRUSTED TO HAVE AN ANSWER.
// Every failure returns a specific contract code. We NEVER fall back to
// plausible-looking invented text, and we never return a partial-but-labelled-
// -as-complete transcript:
//   400 INVALID_URL      not a YouTube http(s) URL with a plausible video id
//   422 NO_TRANSCRIPT    the video has no captions, is private/removed, or the
//                        caption response could not be read into cues
//   502 FETCH_FAILED     YouTube could not be reached, timed out, or answered
//                        with a non-OK status, or the track was too large
// A transcript is only ever returned when real caption cues were parsed.
//
// The transcript itself is UNTRUSTED INPUT (it is page content, and a video
// title can contain anything). The route stores it as vector metadata that
// retrieval.js builds citations from; nothing here derives facts from it.
// =============================================================================

import { ApiError } from '../../middleware/errors.js';

/* ---------------------------------------------------------------- tunables */

// Server env overrides, all optional — the defaults are the documented
// behaviour. Mirrors the style used in server/routes/sources.js.
const TIMEOUT_MS = Number(process.env.YOUTUBE_TIMEOUT_MS ?? 15000);
const SEGMENT_SECONDS = Number(process.env.YOUTUBE_SEGMENT_SECONDS ?? 30);
const SEGMENT_MAX_CHARS = Number(process.env.YOUTUBE_SEGMENT_MAX_CHARS ?? 600);
const MAX_TRACK_BYTES = Number(process.env.YOUTUBE_MAX_TRACK_BYTES ?? 16) * 1024 * 1024;

// A browser-ish User-Agent. YouTube serves an empty body to some clients;
// this one is answered, verified live 2026-10-14.
const USER_AGENT = 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36';

/* ===================================================================== */
/* === SITE-SPECIFIC PARSING — the only YouTube-shaped code lives here === */
/* ===================================================================== */

// --- 1. URL shapes -----------------------------------------------------
//
// We accept the documented watch/shorts/embed forms on YouTube's own hosts and
// nothing else. A host not on this list is not YouTube, however the path looks.
const YOUTUBE_HOSTS = new Set([
  'youtube.com',
  'www.youtube.com',
  'm.youtube.com',
  'music.youtube.com',
  'youtu.be',
  'www.youtu.be',
  'youtube-nocookie.com',
  'www.youtube-nocookie.com',
]);

// A YouTube video id is 11 characters of the URL-safe base64 alphabet.
// This is what stops `?v=javascript:alert(1)` and `?v=../../etc/passwd` from
// ever reaching a URL we build.
const VIDEO_ID_PATTERN = /^[A-Za-z0-9_-]{11}$/;

// Path → how the video id is carried. `watch` reads the `v` query parameter;
// the rest read the first path segment.
const PATH_MODES = new Map([
  ['watch', 'query'],
  ['shorts', 'segment'],
  ['embed', 'segment'],
  ['live', 'segment'],
  ['v', 'segment'],
]);

/**
 * Parse a pasted URL into `{ videoId, canonicalUrl }`, or `null` when it is
 * not a YouTube URL with a plausible video id.
 *
 * Rejects (returns null): non-http(s) schemes (`javascript:`, `data:`, …),
 * non-YouTube hosts, a missing/short/long id, and an over-long id.
 */
export function parseYouTubeUrl(value) {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  if (trimmed === '' || trimmed.length > 2048) return null;

  // A student often pastes "youtube.com/watch?v=…" with no scheme. Prefixing
  // https is safe: the host still has to be on YOUTUBE_HOSTS below, so
  // "javascript:alert(1)" or "data:text/html" can never become a YouTube URL.
  const hasScheme = /^[a-z][a-z0-9+.-]*:/i.test(trimmed);
  const candidate = hasScheme ? trimmed : `https://${trimmed}`;

  let parsed;
  try {
    parsed = new URL(candidate);
  } catch {
    return null;
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return null;
  if (!YOUTUBE_HOSTS.has(parsed.hostname.toLowerCase())) return null;

  const segments = parsed.pathname.split('/').filter((part) => part !== '');
  const host = parsed.hostname.toLowerCase();
  const mode = PATH_MODES.get(segments[0] ?? '');

  let videoId = null;
  if (mode === 'query') {
    videoId = parsed.searchParams.get('v'); // youtube.com/watch?v=<id>
  } else if (mode === 'segment') {
    videoId = segments[1] ?? null; // /shorts, /embed, /live, /v
  } else if (host === 'youtu.be' || host === 'www.youtu.be') {
    videoId = segments[0] ?? null; // youtu.be/<id>
  }
  if (typeof videoId !== 'string' || !VIDEO_ID_PATTERN.test(videoId)) return null;

  // The canonical form is what we store as the source URL, so a pasted
  // `m.youtube.com/shorts/xyz` and a pasted full URL land on one source shape.
  return { videoId, canonicalUrl: `https://www.youtube.com/watch?v=${videoId}` };
}

// --- 2. the innertube player call ---------------------------------------
//
// The ANDROID client is the one identity that (a) reports playability
// honestly and (b) hands back caption URLs that actually answer. It needs no
// API key. These strings are the seam: if YouTube changes the client version
// or stops accepting this client, the call fails here and the route reports
// NO_TRANSCRIPT/FETCH_FAILED — it does not guess.
const ANDROID_CLIENT = { clientName: 'ANDROID', clientVersion: '20.10.38', androidSdkVersion: 30, hl: 'en', gl: 'US' };

/** POST the player request and return the parsed JSON, or throw FETCH_FAILED. */
async function fetchPlayerResponse(videoId) {
  const response = await fetch('https://www.youtube.com/youtubei/v1/player?prettyPrint=false', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'User-Agent': USER_AGENT,
      'Accept-Language': 'en-US,en;q=0.9',
      'X-Youtube-Client-Name': '3', // YouTube's numeric id for the ANDROID client
      'X-Youtube-Client-Version': ANDROID_CLIENT.clientVersion,
      'X-Goog-Api-Format-Version': '2',
    },
    body: JSON.stringify({
      context: { client: ANDROID_CLIENT },
      videoId,
      contentCheckOk: true,
      racyCheckOk: true,
    }),
    signal: AbortSignal.timeout(TIMEOUT_MS),
  });

  if (!response.ok) {
    throw new ApiError(502, 'FETCH_FAILED',
      `YouTube could not be read for this video (HTTP ${response.status}). Try again in a moment.`);
  }
  const body = await response.text();
  if (!body) {
    throw new ApiError(502, 'FETCH_FAILED', 'YouTube returned an empty response for this video. Try again in a moment.');
  }
  try {
    return JSON.parse(body);
  } catch {
    throw new ApiError(502, 'FETCH_FAILED', 'YouTube answered in a shape this build does not understand. The video page may have changed.');
  }
}

/** `captions.playerCaptionsTracklistRenderer.captionTracks`, or []. */
export function readCaptionTracks(playerResponse) {
  const tracks = playerResponse?.captions?.playerCaptionsTracklistRenderer?.captionTracks;
  return Array.isArray(tracks) ? tracks : [];
}

/** The human name of a track: `name.simpleText`, else the first run, else the code. */
function trackName(track) {
  const simple = track?.name?.simpleText;
  if (typeof simple === 'string' && simple.trim() !== '') return simple.trim();
  const run = track?.name?.runs?.[0]?.text;
  if (typeof run === 'string' && run.trim() !== '') return run.trim();
  return typeof track?.languageCode === 'string' ? track.languageCode : '';
}

/**
 * Pick the track to read. Preference order:
 *   1. the requested language, human-written
 *   2. the requested language, auto-generated
 *   3. the first human-written track of any language
 *   4. the first auto-generated track of any language
 *
 * Human-written captions are preferred because they are the accurate ones; the
 * reported `isAutoGenerated` flag lets the caller say which was actually used.
 * Returns `{ track, name, languageCode, isAutoGenerated }` or null.
 */
export function chooseCaptionTrack(tracks, preferredLanguage = 'en') {
  const wanted = typeof preferredLanguage === 'string' ? preferredLanguage.trim().toLowerCase() : '';
  const isAuto = (track) => track?.kind === 'asr' || /auto-generated/i.test(trackName(track));
  const matchesLanguage = (track) => String(track?.languageCode ?? '').toLowerCase() === wanted;

  const chosen = tracks.find((t) => matchesLanguage(t) && !isAuto(t))
    ?? tracks.find((t) => matchesLanguage(t))
    ?? tracks.find((t) => !isAuto(t))
    ?? tracks[0];
  if (!chosen) return null;

  return {
    track: chosen,
    name: trackName(chosen),
    languageCode: typeof chosen.languageCode === 'string' ? chosen.languageCode : '',
    isAutoGenerated: isAuto(chosen),
  };
}

/** GET a caption track's `baseUrl` and return its body, or throw. */
async function fetchTrackText(baseUrl, videoId) {
  const response = await fetch(baseUrl, {
    headers: { 'User-Agent': USER_AGENT, 'Accept-Language': 'en-US,en;q=0.9' },
    signal: AbortSignal.timeout(TIMEOUT_MS),
  });
  if (!response.ok) {
    throw new ApiError(502, 'FETCH_FAILED',
      `YouTube's caption track for this video could not be read (HTTP ${response.status}). Try again in a moment.`);
  }
  // Read as text but refuse an absurdly large body before it lands in memory.
  const declared = Number(response.headers.get('content-length') ?? 0);
  if (Number.isFinite(declared) && declared > MAX_TRACK_BYTES) {
    throw new ApiError(502, 'FETCH_FAILED', 'This video\'s caption track is too large to process. Try a shorter video.');
  }
  const body = await response.text();
  if (body.length > MAX_TRACK_BYTES) {
    throw new ApiError(502, 'FETCH_FAILED', 'This video\'s caption track is too large to process. Try a shorter video.');
  }
  if (body.trim() === '') {
    // YouTube answers 200 with an EMPTY body when it declines to serve the
    // track (bot checks, a PO-token requirement, a region block). That is not
    // a transcript, and we must never treat it as one.
    throw new ApiError(422, 'NO_TRANSCRIPT',
      `YouTube returned no caption data for "${videoId}". Its captions may be region-blocked or the request may have been refused.`);
  }
  return body;
}

// --- 3. the timedtext XML ----------------------------------------------
//
// `<timedtext format="3"><body><p t="18640" d="3240">text</p>…</body></timedtext>`
// `t` = start in milliseconds, `d` = duration in milliseconds. The text can
// contain HTML entities and newlines (manual captions wrap lines), and rarely
// an inline tag. All are normalised here, once.
const CUE_ELEMENT = /<p\b([^>]*)>([\s\S]*?)<\/p>/g;

function attribute(attributes, name) {
  const match = new RegExp(`\\b${name}\\s*=\\s*"([^"]*)"`).exec(attributes);
  return match ? match[1] : null;
}

/** Decode the entities YouTube emits, drop any inline tag, flatten newlines. */
function normalizeCueText(raw) {
  return raw
    .replace(/<[^>]*>/g, ' ') // an inline <font>/<s> wrapper, if any
    .replace(/&#39;/g, '\'')
    .replace(/&quot;/g, '"')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\\[nN]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Parse a `<timedtext>` body into cues: `[{ startSeconds, text }]`.
 * Returns `[]` when the body is not the shape we can read — the caller turns
 * that into NO_TRANSCRIPT rather than inventing text.
 */
export function parseTimedText(body) {
  const cues = [];
  for (const match of String(body ?? '').matchAll(CUE_ELEMENT)) {
    const start = Number(attribute(match[1], 't') ?? NaN);
    const text = normalizeCueText(match[2] ?? '');
    if (!Number.isFinite(start) || start < 0 || text === '') continue;
    cues.push({ startSeconds: start / 1000, text });
  }
  return cues;
}

/* ======================= END OF SITE-SPECIFIC PARSING =================== */

/* ------------------------------------------------------- time formatting */

/** 512 → "00:08:32"; 212 → "00:03:32". Always `hh:mm:ss`, which is the form
 *  retrieval.js#toCitation renders (it normalises `mm:ss` too, but emitting the
 *  full form keeps one convention end to end). */
export function formatTimecode(totalSeconds) {
  const total = Math.floor(Number(totalSeconds));
  if (!Number.isFinite(total) || total < 0) return null;
  const pad = (value) => String(value).padStart(2, '0');
  return `${pad(Math.floor(total / 3600))}:${pad(Math.floor((total % 3600) / 60))}:${pad(total % 60)}`;
}

/* ------------------------------------------------------ segment building */

/**
 * Group cues into segments for `chunkSegments()`.
 *
 * Each segment carries ONE starting timecode, so the chunk it becomes cites
 * exactly that second:
 *   text      "[00:00:12] first cue [00:00:18] second cue …" — the `[hh:mm:ss]`
 *             markers are the transcript chunker's unit boundaries
 *             (services/chunker.js UNIT_SEPARATORS.transcript), and they are
 *             also retrieval.js's text fallback when metadata has no timecode.
 *   location  { timecode: "00:00:12" }   → stored as chunk metadata `timecode`
 *             → citation `location.timestamp: "00:00:12"`.
 *
 * A segment is closed when the NEXT cue would start more than `SEGMENT_SECONDS`
 * after this segment's first cue, or when it would exceed `SEGMENT_MAX_CHARS`.
 * Both bounds are what keep a segment under the transcript chunk size (700), so
 * one segment becomes exactly one chunk with one exact timestamp instead of one
 * chunk whose timestamp is up to a minute early.
 */
export function buildTranscriptSegments(cues) {
  const segments = [];
  let group = null;

  const flush = () => {
    if (!group) return;
    if (group.parts.length === 0) return;
    // Every cue already carries its own `[hh:mm:ss]` marker (the chunker's unit
    // boundary and retrieval's text fallback), so the segment needs no prefix.
    const body = group.parts.join(' ');
    segments.push({
      text: body,
      location: { timecode: formatTimecode(group.startSeconds) },
      startSeconds: group.startSeconds,
    });
    group = null;
  };

  for (const cue of Array.isArray(cues) ? cues : []) {
    if (!cue || typeof cue.text !== 'string' || cue.text.trim() === '') continue;
    const startSeconds = Number(cue.startSeconds);
    if (!Number.isFinite(startSeconds) || startSeconds < 0) continue;

    const closesGroup = group !== null
      && (startSeconds - group.startSeconds > SEGMENT_SECONDS
        || group.textLength + cue.text.length + 1 > SEGMENT_MAX_CHARS);

    if (group === null || closesGroup) {
      flush();
      group = { startSeconds, parts: [], textLength: 0 };
    }
    group.parts.push(`[${formatTimecode(startSeconds)}] ${cue.text.trim()}`);
    group.textLength += cue.text.length + 12; // cue text + its marker
  }
  flush();

  // `startSeconds` was only a build-time aid; the contract segment shape is
  // { text, location } and that is what the route persists.
  return segments.map(({ text, location }) => ({ text, location }));
}

/* ------------------------------------------------------ public entry point */

/**
 * Fetch one video's captions and turn them into transcript segments.
 *
 * @param {object}  options
 * @param {string}  options.url        a YouTube URL (validated here again, cheap)
 * @param {string} [options.language]  preferred caption language (default 'en')
 * @returns {Promise<object>} { videoId, title, url, durationSeconds, language,
 *                             isAutoGenerated, segments, cueCount, charCount }
 * @throws {ApiError} 400 INVALID_URL · 422 NO_TRANSCRIPT · 502 FETCH_FAILED
 */
export async function fetchYouTubeTranscript({ url, language } = {}) {
  const parsed = parseYouTubeUrl(url);
  if (!parsed) {
    throw new ApiError(400, 'INVALID_URL',
      'That is not a YouTube video link. Paste a youtube.com/watch, youtu.be or youtube.com/shorts link.');
  }
  const { videoId, canonicalUrl } = parsed;

  let player;
  try {
    player = await fetchPlayerResponse(videoId);
  } catch (err) {
    if (err instanceof ApiError) throw err;
    // A timeout or a DNS/TLS failure: name it as a fetch failure, not a crash.
    const kind = err?.name === 'TimeoutError' || err?.name === 'AbortError' ? 'timed out' : 'could not be reached';
    throw new ApiError(502, 'FETCH_FAILED', `YouTube ${kind} while reading this video. Try again in a moment.`);
  }

  const tracks = readCaptionTracks(player);
  if (tracks.length === 0) {
    const status = player?.playabilityStatus;
    const reason = typeof status?.reason === 'string' && status.reason.trim() !== '' ? status.reason.trim() : null;
    if (typeof status?.status === 'string' && status.status !== 'OK' && reason) {
      throw new ApiError(422, 'NO_TRANSCRIPT',
        `YouTube could not read this video ("${reason}") — it may be private, removed, or region-blocked.`);
    }
    throw new ApiError(422, 'NO_TRANSCRIPT',
      'This video has no captions, so there is nothing to turn into study notes. Try a video that has subtitles.');
  }

  const chosen = chooseCaptionTrack(tracks, typeof language === 'string' ? language : 'en');
  if (!chosen) {
    throw new ApiError(422, 'NO_TRANSCRIPT', 'This video has no captions, so there is nothing to turn into study notes.');
  }

  const trackBody = await fetchTrackText(chosen.track.baseUrl, videoId);
  const cues = parseTimedText(trackBody);
  if (cues.length === 0) {
    throw new ApiError(422, 'NO_TRANSCRIPT',
      'YouTube returned a caption track for this video, but it contained no readable text.');
  }

  const segments = buildTranscriptSegments(cues);
  if (segments.length === 0) {
    throw new ApiError(422, 'NO_TRANSCRIPT', 'The caption track could not be turned into readable passages.');
  }

  const details = player?.videoDetails ?? {};
  const title = typeof details.title === 'string' && details.title.trim() !== '' ? details.title.trim() : canonicalUrl;
  const durationSeconds = Number(details.lengthSeconds);

  return {
    videoId,
    title,
    url: canonicalUrl,
    durationSeconds: Number.isFinite(durationSeconds) && durationSeconds >= 0 ? Math.floor(durationSeconds) : null,
    language: chosen.languageCode || 'unknown',
    isAutoGenerated: chosen.isAutoGenerated,
    segments,
    cueCount: cues.length,
    charCount: segments.reduce((sum, segment) => sum + segment.text.length, 0),
  };
}
